local WateringSpikeMaker = {}
local PRODUCTS = {
    iron_wateringspike = { name = "Železni zalivalna konica", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zalivalna konica za vrtove." },
    bronze_wateringspike = { name = "Bronast zalivalna konica", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zalivalna konica za vrtove." },
    silver_wateringspike = { name = "Srebrn zalivalna konica", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zalivalna konica za vrtove." },
    gilded_wateringspike = { name = "Pozlačen zalivalna konica", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zalivalna konica za vrtove." },
    jewel_set_wateringspike = { name = "Draguljast zalivalna konica", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zalivalna konica za vrtove." },
    royal_sovereign_wateringspike = { name = "Kraljevski suveren zalivalna konica", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zalivalna konica z biseri za krono." },
}
local BUILDINGS = {
    wateringspike_workshop = { name = "Wateringspike delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    wateringspike_house = { name = "Wateringspike hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_wateringspike_atelier = { name = "Mojstrski wateringspike atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_wateringspike_palace = { name = "Suverena wateringspike palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
WateringSpikeMaker.ironStock = 14; WateringSpikeMaker.bronzeStock = 12; WateringSpikeMaker.woodStock = 12; WateringSpikeMaker.leatherStock = 10; WateringSpikeMaker.silverStock = 8; WateringSpikeMaker.goldStock = 6; WateringSpikeMaker.jewelStock = 4; WateringSpikeMaker.pearlStock = 4
WateringSpikeMaker.productStock = {}; WateringSpikeMaker.buildings = {}; WateringSpikeMaker.maker = nil; WateringSpikeMaker.activeMaking = {}; WateringSpikeMaker.totalProducts = 0; WateringSpikeMaker.dayTimer = 0
function WateringSpikeMaker.init() WateringSpikeMaker.ironStock=14; WateringSpikeMaker.bronzeStock=12; WateringSpikeMaker.woodStock=12; WateringSpikeMaker.leatherStock=10; WateringSpikeMaker.silverStock=8; WateringSpikeMaker.goldStock=6; WateringSpikeMaker.jewelStock=4; WateringSpikeMaker.pearlStock=4; WateringSpikeMaker.productStock={}; WateringSpikeMaker.buildings={}; WateringSpikeMaker.maker=nil; WateringSpikeMaker.activeMaking={}; WateringSpikeMaker.totalProducts=0; WateringSpikeMaker.dayTimer=0; print("[WateringSpikeMaker] Royal Watering Spike Maker System initialized (6 products, 4 buildings)") end
function WateringSpikeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WateringSpikeMaker.maker={name=n or ("Koničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Koničar najet: %s (spretnost: %d)",WateringSpikeMaker.maker.name,s),"success") end; return true end
function WateringSpikeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WateringSpikeMaker.build(id) local ok,e=WateringSpikeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WateringSpikeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WateringSpikeMaker.getQualityBonus() local b=0; for _,bd in ipairs(WateringSpikeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WateringSpikeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WateringSpikeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and WateringSpikeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and WateringSpikeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WateringSpikeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WateringSpikeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WateringSpikeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WateringSpikeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WateringSpikeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WateringSpikeMaker.buildings==0 then return false,"Potrebna konična delavnica" end; if not WateringSpikeMaker.maker then return false,"Potreben konicar" end; return true end
function WateringSpikeMaker.make(pt,qty) qty=qty or 1; local ok,e=WateringSpikeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WateringSpikeMaker.ironStock=WateringSpikeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then WateringSpikeMaker.bronzeStock=WateringSpikeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then WateringSpikeMaker.woodStock=WateringSpikeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WateringSpikeMaker.leatherStock=WateringSpikeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WateringSpikeMaker.silverStock=WateringSpikeMaker.silverStock-d.silverCost*qty end; if d.goldCost then WateringSpikeMaker.goldStock=WateringSpikeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WateringSpikeMaker.jewelStock=WateringSpikeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WateringSpikeMaker.pearlStock=WateringSpikeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WateringSpikeMaker.maker then t=math.max(1,t-math.floor(WateringSpikeMaker.maker.skill/13)) end; table.insert(WateringSpikeMaker.activeMaking,{id="wateringspike_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WateringSpikeMaker.completeMaking(m) local q=1.0+(WateringSpikeMaker.getQualityBonus()/100); if WateringSpikeMaker.maker then q=q+(WateringSpikeMaker.maker.skill/140) end; q=math.min(2.5,q); WateringSpikeMaker.productStock[m.productType]=(WateringSpikeMaker.productStock[m.productType] or 0)+m.quantity; WateringSpikeMaker.totalProducts=WateringSpikeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WateringSpikeMaker.maker then WateringSpikeMaker.maker.itemsMade=WateringSpikeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WateringSpikeMaker.maker.skill=math.min(100,WateringSpikeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Konica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wateringspike.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function WateringSpikeMaker.update(dt) if not _G.state then return end; WateringSpikeMaker.dayTimer=WateringSpikeMaker.dayTimer+dt; if WateringSpikeMaker.dayTimer>=30 then WateringSpikeMaker.dayTimer=0; for i=#WateringSpikeMaker.activeMaking,1,-1 do local m=WateringSpikeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WateringSpikeMaker.completeMaking(m); table.remove(WateringSpikeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WateringSpikeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WateringSpikeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WateringSpikeMaker.getStats() return {ironStock=WateringSpikeMaker.ironStock,bronzeStock=WateringSpikeMaker.bronzeStock,woodStock=WateringSpikeMaker.woodStock,leatherStock=WateringSpikeMaker.leatherStock,silverStock=WateringSpikeMaker.silverStock,goldStock=WateringSpikeMaker.goldStock,jewelStock=WateringSpikeMaker.jewelStock,pearlStock=WateringSpikeMaker.pearlStock,productStock=WateringSpikeMaker.productStock,numBuildings=#WateringSpikeMaker.buildings,hasMaker=WateringSpikeMaker.maker~=nil,makerName=WateringSpikeMaker.maker and WateringSpikeMaker.maker.name or "—",makerSkill=WateringSpikeMaker.maker and WateringSpikeMaker.maker.skill or 0,activeMaking=#WateringSpikeMaker.activeMaking,totalProducts=WateringSpikeMaker.totalProducts} end
return WateringSpikeMaker
